--
-- Estructura de tabla para la tabla `posiciones`
--

CREATE TABLE `posiciones` (
  `id` int(11) NOT NULL,
  `temporada` varchar(9) NOT NULL,
  `torneo` enum('Apertura','Clausura') NOT NULL,
  `posicion` tinyint(3) UNSIGNED NOT NULL,
  `equipo` varchar(60) NOT NULL,
  `pj` smallint(6) DEFAULT NULL,
  `g` smallint(6) DEFAULT NULL,
  `e` smallint(6) DEFAULT NULL,
  `p` smallint(6) DEFAULT NULL,
  `gf` smallint(6) DEFAULT NULL,
  `gc` smallint(6) DEFAULT NULL,
  `pts` smallint(6) DEFAULT NULL,
  `grupo` tinyint(3) UNSIGNED DEFAULT NULL,
  `posicion_grupo` tinyint(3) UNSIGNED DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

